func work(ctx context.Context, ch <-chan Job) error {
    for {
        select {
        case <-ctx.Done():
            return ctx.Err()     // Canceled ou DeadlineExceeded
        case j, ok := <-ch:
            if !ok { return nil }
            process(ctx, j)
        }
    }
}
